// chip name
unsigned char *gx_get_chip_name(void)
{
#define GX_CHIP_NAME_LEN  20
	static unsigned char name[GX_CHIP_NAME_LEN] = {0};

#if defined(CONFIG_ARCH_CKMMU_GX3201) || defined(CONFIG_ARCH_CKMMU_GX3113C)
	printf("[%s %d]: GX3201/GX3113C unsupport now!\n", __func__, __LINE__);
#else
	unsigned int name_reg = CONFIG_BASE_MMU + CONFIG_CHIP_NAME0;
	unsigned int name_len = 12;
	memcpy((void*)name, (const void *)name_reg, name_len);
#if defined(CONFIG_ARCH_ARM_SIRIUS) || defined(CONFIG_ARCH_CKMMU_TAURUS)|| defined(CONFIG_ARCH_CKMMU_GEMINI) \
	|| defined(CONFIG_ARCH_CKMMU_CYGNUS) || defined(CONFIG_ARCH_ARM_CANOPUS) || defined(CONFIG_ARCH_ARM_VEGA) || defined(CONFIG_ARCH_CKMMU_SCORPIO) \
	|| defined(CONFIG_ARCH_CKMMU_SCORPIO_TAURUS)
	data_reverse(name, name_len);
#endif

#endif

	return name;
}

// public id
unsigned char *gx_get_chip_id(void)
{
#define MAX_GX_CHIP_ID_LEN  20
	static unsigned char id[MAX_GX_CHIP_ID_LEN] = {0};

	unsigned int id_reg = CONFIG_BASE_MMU + CONFIG_PUBLIC_ID_L;
	unsigned int id_len = GX_CHIP_ID_LEN;

	memcpy((void*)id, (const void *)id_reg, id_len);

#if defined(CONFIG_ARCH_ARM_SIRIUS) || defined(CONFIG_ARCH_CKMMU_TAURUS)|| defined(CONFIG_ARCH_CKMMU_GEMINI) \
	|| defined(CONFIG_ARCH_CKMMU_CYGNUS) || defined(CONFIG_ARCH_ARM_CANOPUS) || defined(CONFIG_ARCH_ARM_VEGA) || defined(CONFIG_ARCH_CKMMU_SCORPIO) \
	|| defined(CONFIG_ARCH_CKMMU_SCORPIO_TAURUS)
	data_reverse(id, id_len);
#endif

	return id;
}

// chip id
unsigned int gxcore_chip_probe(void)
{
	unsigned int chipid;

#ifdef CONFIG_ARCH_CKMMU_GX6605S
	chipid = 0x6605;
#else
	chipid = *((volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CHIP_ID));
	chipid = ((chipid >> 14) & 0xFFFF);
#endif

	return chipid;
}

unsigned int gxcore_chip_sub_probe(void) {

#ifdef CONFIG_ARCH_CKMMU_GX6605S
	static unsigned int gx_chipsubid = 0xFFFFFFFF;

	if (gx_chipsubid != 0xFFFFFFFF)
		return gx_chipsubid;

	if (0 == REG_CHIP_6605S_PROBE)
		gx_chipsubid = 0;
	else
		gx_chipsubid = 1;

	return gx_chipsubid;
#endif
	return 0;
}

unsigned int gxcore_chip_version(void)
{
#if defined(CONFIG_ARCH_CKMMU_CYGNUS) || defined(CONFIG_ARCH_CKMMU_SCORPIO) || defined(CONFIG_ARCH_CKMMU_SCORPIO_TAURUS)
	unsigned int value;
	unsigned int version = 0;

	value = *((volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CHIP_ID));
	version |= ((value & 0x3F) << 2) | (value >> 30);

	return version;
#elif defined(CONFIG_ARCH_ARM_CANOPUS)
	unsigned int value;
	unsigned int version = 0;

	value = *((volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_CHIP_ID));
	version |= ((value & 0x3FFF) << 2) | (value >> 30);

	return version;
#else
	return 1;
#endif

}

int gxcore_chip_nagra_mode(void)
{
#ifdef CONFIG_ARCH_ARM_VEGA
	unsigned int secure_state = 0;

	secure_state = *(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_SECURE_STATE);

	if (((secure_state >> 10) & 0x3) == 1)
		return 1;

	return 0;
#else
	return 0;
#endif
}

int gxcore_chip_tee_secure_enable(void)
{
#ifdef CONFIG_ARCH_ARM_VEGA
	unsigned int secure_status = 0;

	secure_status = *(volatile unsigned int *)(CONFIG_BASE_MMU + CONFIG_SECURE_STATUS);

	if (((secure_status >> 15) & 0x3) == 1)
		return 1;

	return 0;
#else
	return 0;
#endif
}
